CREATE DATABASE IF NOT EXISTS hwinfo CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE hwinfo;
CREATE TABLE users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,username VARCHAR(100) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('admin','expert','user') NOT NULL DEFAULT 'user',full_name VARCHAR(160) NOT NULL,active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE personnel(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,personnel_code VARCHAR(80) NOT NULL UNIQUE,full_name VARCHAR(160) NOT NULL,department VARCHAR(160) NULL,location VARCHAR(255) NULL,active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE import_batches(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,sha256 CHAR(64) NOT NULL UNIQUE,original_name VARCHAR(255) NOT NULL,row_count INT UNSIGNED NOT NULL,status ENUM('processing','completed','failed') NOT NULL DEFAULT 'processing',created_by BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE computers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,import_batch_id BIGINT UNSIGNED NULL,computer_name VARCHAR(160) NOT NULL,user_name VARCHAR(160) NULL,manufacturer VARCHAR(160) NULL,model VARCHAR(160) NULL,system_serial VARCHAR(255) NULL,system_uuid VARCHAR(255) NULL,os_name VARCHAR(255) NULL,os_version VARCHAR(100) NULL,os_build VARCHAR(100) NULL,personnel_id BIGINT UNSIGNED NULL,location VARCHAR(255) NULL,asset_number VARCHAR(100) NULL UNIQUE,raw_json JSON NOT NULL,status ENUM('pending','approved','rejected','deleted') NOT NULL DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(status),INDEX(computer_name),INDEX(system_serial),FOREIGN KEY(import_batch_id) REFERENCES import_batches(id) ON DELETE SET NULL,FOREIGN KEY(personnel_id) REFERENCES personnel(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE printers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,computer_id BIGINT UNSIGNED NULL,name VARCHAR(255) NOT NULL,raw_json JSON NULL,status ENUM('pending','approved','rejected','deleted') NOT NULL DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(computer_id) REFERENCES computers(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE scanners(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,computer_id BIGINT UNSIGNED NULL,name VARCHAR(255) NOT NULL,raw_json JSON NULL,status ENUM('pending','approved','rejected','deleted') NOT NULL DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(computer_id) REFERENCES computers(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE monitors(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,computer_id BIGINT UNSIGNED NULL,name VARCHAR(255) NOT NULL,raw_json JSON NULL,status ENUM('pending','approved','rejected','deleted') NOT NULL DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(computer_id) REFERENCES computers(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE audit_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,action VARCHAR(40) NOT NULL,entity VARCHAR(80) NOT NULL,entity_id BIGINT UNSIGNED NOT NULL,before_json JSON NULL,after_json JSON NULL,ip_address VARCHAR(45) NULL,user_agent VARCHAR(500) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(entity,entity_id),INDEX(created_at),FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
